<script setup lang="ts">
import {computed,ref} from 'vue'
import {useWorkbench} from '../stores/scope'
import {number,percent} from '../domain/types'
import {categoryPulse,type PulseRow} from '../domain/categoryPulse'
const store=useWorkbench(),emit=defineEmits<{inspect:[];evidence:[]}>()
const mode=ref<'shares'|'concentration'>('shares'),sort=ref('exposure')
const pulse=computed(()=>store.model?categoryPulse(store.model,store.metric):null)
const rows=computed(()=>{const rows=pulse.value?.rows.slice()??[];return sort.value==='gap'?rows.sort((a,b)=>(a.gapPP??Infinity)-(b.gapPP??Infinity)||a.rank-b.rank):rows})
const selected=computed(()=>pulse.value?.rows.find(r=>r.id===store.focus)??pulse.value?.rows[0])
const label=computed(()=>store.metric==='click'?'点击':'购买反馈')
const ready=computed(()=>store.categoryProductsKey===store.model?.scope_id+'|'+selected.value?.id)
const pct=(v:number|null|undefined)=>v==null?'—':(v*100).toFixed(v>0&&v<.001?3:1)+'%'
const gap=(v:number|null)=>v==null?'—':(v>0?'+':'')+v.toFixed(1)
const points=(key:'cumExposure'|'cumFeedback')=>{const rows=pulse.value?.rows??[];return ['48,268',...rows.filter(r=>r[key]!=null).map(r=>`${48+512*r.rank/rows.length},${268-232*r[key]!}`)].join(' ')}
async function choose(row:PulseRow){const pending=store.setCategory(row.id);if(matchMedia('(max-width:1100px)').matches)emit('inspect');await pending}
function pickCurve(e:MouseEvent){const rows=pulse.value?.rows??[];if(!rows.length)return;const rect=(e.currentTarget as SVGElement).getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*600;const n=Math.max(1,Math.min(rows.length,Math.round((x-48)/512*rows.length)));choose(rows[n-1])}
async function openProduct(id:string){await store.showProduct(id)}
</script>
<template>
<section v-if="pulse" class="category-pulse" aria-label="类目体检" :aria-busy="store.loading">
 <div class="cp-top"><div class="cp-modes" role="group" aria-label="类目体检图形"><button :class="{active:mode==='shares'}" :aria-pressed="mode==='shares'" @click="mode='shares'">份额对照</button><button :class="{active:mode==='concentration'}" :aria-pressed="mode==='concentration'" @click="mode='concentration'">曝光集中度</button></div><div class="cp-metric" role="group" aria-label="类目反馈指标"><button :class="{active:store.metric==='click'}" :aria-pressed="store.metric==='click'" @click="store.metric='click'">点击</button><button :class="{active:store.metric==='purchase_feedback'}" :aria-pressed="store.metric==='purchase_feedback'" @click="store.metric='purchase_feedback'">购买反馈</button></div></div>
 <div v-if="!pulse.consistent" class="cp-empty" role="alert">类目合计与范围不一致，请重新读取快照。</div>
 <div v-else-if="!pulse.rows.length" class="cp-empty">当前范围没有曝光，暂不计算份额。</div>
 <div v-else class="cp-layout">
  <section class="cp-chart"><div class="cp-summary"><div><span>前 {{Math.min(3,pulse.rows.length)}} 类目曝光</span><strong>{{percent(pulse.top3)}}</strong></div><div><span>覆盖 80% 曝光</span><strong>{{pulse.n80}}<small> / {{pulse.rows.length}} 类</small></strong></div></div>
   <div class="cp-chart-head"><div class="cp-legend"><span><i class="cp-green"/>曝光份额</span><span><i class="cp-amber"/>{{label}}份额</span></div><label v-if="mode==='shares'">排序<select v-model="sort" aria-label="类目体检排序"><option value="exposure">曝光优先</option><option value="gap">份额差从低到高</option></select></label></div>
   <template v-if="mode==='shares'"><div class="cp-axis"><span>类目 · 曝光</span><div><b>0%</b><b>{{pct(pulse.shareMax/2)}}</b><b>{{pct(pulse.shareMax)}}</b></div><span>差（百分点）</span></div><div class="cp-row-list"><button v-for="row in rows" :key="row.id" class="cp-row" :class="{selected:selected?.id===row.id}" :aria-pressed="selected?.id===row.id" :data-id="row.id" :data-e="row.E" :data-n="row.feedback" :data-eshare="row.exposureShare" :data-nshare="row.feedbackShare" :aria-label="`${row.name}，曝光份额${pct(row.exposureShare)}，${label}份额${pct(row.feedbackShare)}，差${gap(row.gapPP)}个百分点`" @click="choose(row)"><span class="cp-row-name"><b :title="row.name">{{row.name}}</b><small>{{number(row.E)}}</small></span><span class="cp-lane"><i v-if="row.feedbackShare!=null" class="cp-bridge" :style="{left:100*Math.min(row.exposureShare,row.feedbackShare)/pulse.shareMax+'%',width:100*Math.abs(row.feedbackShare-row.exposureShare)/pulse.shareMax+'%'}"/><i class="cp-dot cp-green" :style="{left:100*row.exposureShare/pulse.shareMax+'%'}"/><i v-if="row.feedbackShare!=null" class="cp-dot cp-amber" :style="{left:100*row.feedbackShare/pulse.shareMax+'%'}"/></span><strong class="cp-gap">{{gap(row.gapPP)}}</strong></button></div><p class="cp-help">每行两个点：该类曝光 / 全部曝光，该类{{label}} / 全部{{label}}。差值 = {{label}}份额 − 曝光份额。</p></template>
   <template v-else><div class="cp-curve-host"><svg class="cp-curve" viewBox="0 0 600 310" role="img" aria-label="按曝光排序的类目累计份额曲线" @click="pickCurve"><g v-for="v in [0,.5,.8,1]" :key="v"><line x1="48" :y1="268-232*v" x2="560" :y2="268-232*v" :class="{'cp-target':v===.8}"/><text x="36" :y="272-232*v" text-anchor="end">{{v*100}}%</text></g><polygon :points="points('cumExposure')+' 560,268'" fill="#35816b12"/><polyline :points="points('cumExposure')" class="cp-line exposure"/><polyline v-if="pulse.totalN>0" :points="points('cumFeedback')" class="cp-line feedback"/><g v-if="selected"><line class="cp-crosshair" :x1="48+512*selected.rank/pulse.rows.length" y1="36" :x2="48+512*selected.rank/pulse.rows.length" y2="268"/><circle :cx="48+512*selected.rank/pulse.rows.length" :cy="268-232*selected.cumExposure" r="5" fill="#347c66"/><circle v-if="selected.cumFeedback!=null" :cx="48+512*selected.rank/pulse.rows.length" :cy="268-232*selected.cumFeedback" r="5" fill="#c68138"/></g><text x="48" y="292">0 类</text><text x="560" y="292" text-anchor="end">{{pulse.rows.length}} 类</text><text x="304" y="304" text-anchor="middle">按曝光从多到少累计类目</text></svg></div><div class="cp-cumulative" v-if="selected"><span>前 {{selected.rank}} 类</span><b>曝光 {{pct(selected.cumExposure)}}</b><b>{{label}} {{pct(selected.cumFeedback)}}</b></div><label class="cp-curve-picker">定位类目<select :value="selected?.id" aria-label="集中度定位类目" @change="choose(pulse.rows.find(r=>r.id===($event.target as HTMLSelectElement).value)!)"><option v-for="r in pulse.rows" :key="r.id" :value="r.id">{{r.rank}} · {{r.name}}</option></select></label></template>
  </section>
  <aside v-if="selected" class="cp-detail" aria-label="类目体检详情"><div class="cp-detail-label">当前类目 <span>{{store.queryKey==='all'?'全部查询':store.query||'空查询'}}</span></div><h2>{{selected.name}}</h2><div class="cp-share-pair"><div><span>曝光份额</span><strong>{{pct(selected.exposureShare)}}</strong><small>{{number(selected.E)}} / {{number(pulse.totalE)}}</small></div><div><span>{{label}}份额</span><strong>{{pct(selected.feedbackShare)}}</strong><small>{{number(selected.feedback)}} / {{number(pulse.totalN)}}</small></div></div><p class="cp-verdict" v-if="selected.gapPP!=null">{{label}}份额{{selected.gapPP<-.05?'少于':selected.gapPP>.05?'多于':'接近'}}曝光份额 <b>{{Math.abs(selected.gapPP).toFixed(1)}} 个百分点</b></p><p v-else class="cp-verdict">范围内没有{{label}}，份额暂不成立。</p><p class="cp-boundary">份额差用于定位构成，不能直接判定类目优劣。</p><div class="cp-rate"><span>该类{{label}} / 曝光</span><b>{{pct(selected.feedbackRate)}}</b></div><div class="cp-products"><h3>选商品，查看同类参照 <small>曝光前 5 件</small></h3><p v-if="!ready" role="status">正在读取类目商品…</p><button v-for="p in ready?store.categoryProducts:[]" :key="p.id" :title="p.title" :disabled="store.loading" @click="openProduct(p.id)"><span>{{p.title}}</span><b>{{number(p.E)}} ↗</b></button><small v-if="ready&&store.categoryProducts.length">这 {{store.categoryProducts.length}} 件覆盖类目 {{pct(store.categoryProducts.reduce((s,p)=>s+p.E,0)/selected.E)}} 曝光</small></div><button class="cp-evidence" :disabled="store.loading||!ready" @click="emit('evidence')">核对类目记录 ↗</button></aside>
 </div>
</section>
</template>
<style src="../theme/categoryPulse.css"></style>
